package com.afaki.refreshp.service;import com.afaki.refreshp.model.Job;import org.springframework.stereotype.Service;import java.util.List;import java.util.ArrayList;@Servicepublic class JobService {    private List<Job> jobs = new ArrayList<>();    public List<Job> getAllJobs() {        return jobs;    }    public Job getJobById(long id) {        for (Job job : jobs) {            if (job.getId() == id) {                return job;            }        }        return null;    }    public Job createJob(Job job) {        jobs.add(job);        return job;    }    public void deleteJobById(long id) {        jobs.remove(id);    }}